const props = $json.output?.properties ?? {};

const value = (key, fallback = '') =>
  String(props[key]?.type ?? $json[key] ?? fallback).trim();

return {
  json: {
    draft_id: value('draft_id'),
    company: value('company'),
    signal: value('signal'),
    channel: value('channel', 'LinkedIn'),
    draft_subject: value('draft_subject'),
    draft_body: value('draft_body'),
    gtm_takeaway: value('gtm_takeaway'),
    why_it_matters: value('why_it_matters'),
    source_url: value('source_url').replace(/^\[|\]$/g, ''),
    source_verified: value('source_verified', 'Yes'),
    confidence: value('confidence', 'High'),
    approval_status: value('approval_status', 'Pending'),
    reviewer_note: value('reviewer_note'),
    approved_at: value('approved_at'),
    processed_status: value('processed_status'),
    processed_at: value('processed_at'),
  },
};

parameters.text:
=You are creating a human-reviewed GTM content draft from one verified market signal.

Use only the source data provided below. Do not invent facts, customers, numbers, quotes, partnerships, product details, or outcomes. If the source does not support a claim, do not include it.

The goal is to create a concise LinkedIn-ready draft that shows how a GTM/operator would turn a market signal into a practical point of view.

Source data:
- Company: {{ $json.company }}
- Topic: {{ $json.topic }}
- Signal type: {{ $json.signal_type }}
- Summary: {{ $json.summary }}
- Source name: {{ $json.source_name }}
- Source URL: {{ $json.source_url }}
- Published date: {{ $json.published_date }}
- Source quality: {{ $json.source_quality }}
- Source verified: {{ $json.source_verified }}

Create one draft with:
1. A clear subject/title.
2. A concise LinkedIn post body.
3. One operational GTM takeaway.
4. One reason this signal matters.
5. A source citation using the source name and URL.

Voice:
- Clear, direct, operator-minded.
- No hype.
- No AI-sounding language.
- No exaggerated claims.
- No “unlock,” “transform,” “revolutionize,” “game-changing,” or similar language.
- Do not mention that this was written by AI.

Return only valid JSON matching the required schema.
